{"version":3,"file":"index.js","sources":["pages/doctor/profile/index.vue","../../../../../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvZG9jdG9yL3Byb2ZpbGUvaW5kZXgudnVl"],"sourcesContent":["<template>\n  <view class=\"profile-page\">\n    <!-- 返回按钮 -->\n    <view class=\"back-section\" @click=\"goBackToSchedule\">\n      <text class=\"back-icon\">‹</text>\n      <text class=\"back-text\">返回医生主界面</text>\n    </view>\n\n    <!-- 医生信息头部 -->\n    <view class=\"profile-header\">\n      <view class=\"avatar-section\">\n        <image class=\"avatar\" :src=\"doctorInfo.avatar\" mode=\"aspectFill\" />\n        <view class=\"doctor-basic\">\n          <text class=\"doctor-name\">{{ doctorInfo.name }}</text>\n          <text class=\"doctor-title\">{{ doctorInfo.title }}</text>\n        </view>\n      </view>\n      <view class=\"doctor-dept\">\n        <text class=\"dept-name\">{{ doctorInfo.department }}</text>\n      </view>\n    </view>\n\n    <!-- 统计数据 -->\n    <view class=\"stats-section\">\n      <view class=\"stat-item\">\n        <text class=\"stat-value\">{{ stats.totalPatients }}</text>\n        <text class=\"stat-label\">累计接诊</text>\n      </view>\n      <view class=\"stat-divider\"></view>\n      <view class=\"stat-item\">\n        <text class=\"stat-value\">{{ stats.todayPatients }}</text>\n        <text class=\"stat-label\">今日接诊</text>\n      </view>\n      <view class=\"stat-divider\"></view>\n      <view class=\"stat-item\">\n        <text class=\"stat-value\">{{ stats.rating }}</text>\n        <text class=\"stat-label\">患者评分</text>\n      </view>\n    </view>\n\n    <!-- 个人信息 -->\n    <view class=\"info-section\">\n      <view class=\"section-title\">\n        <text class=\"title-text\">个人信息</text>\n      </view>\n      <view class=\"info-list\">\n        <view class=\"info-item\" @click=\"showEditDialog('name')\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">👤</text>\n            <text class=\"item-label\">姓名</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.name }}</text>\n            <text class=\"item-arrow\">›</text>\n          </view>\n        </view>\n\n        <view class=\"info-item\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">🏥</text>\n            <text class=\"item-label\">科室</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.department }}</text>\n          </view>\n        </view>\n\n        <view class=\"info-item\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">🎓</text>\n            <text class=\"item-label\">职称</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.title }}</text>\n          </view>\n        </view>\n\n        <view class=\"info-item\" @click=\"showEditDialog('phone')\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">📱</text>\n            <text class=\"item-label\">联系电话</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.phone }}</text>\n            <text class=\"item-arrow\">›</text>\n          </view>\n        </view>\n\n        <view class=\"info-item\" @click=\"showEditDialog('email')\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">📧</text>\n            <text class=\"item-label\">邮箱</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.email }}</text>\n            <text class=\"item-arrow\">›</text>\n          </view>\n        </view>\n      </view>\n    </view>\n\n    <!-- 专业信息 -->\n    <view class=\"info-section\">\n      <view class=\"section-title\">\n        <text class=\"title-text\">专业信息</text>\n      </view>\n      <view class=\"info-list\">\n        <view class=\"info-item\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">🎖️</text>\n            <text class=\"item-label\">执业证号</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.licenseNumber }}</text>\n          </view>\n        </view>\n\n        <view class=\"info-item\">\n          <view class=\"item-left\">\n            <text class=\"item-icon\">⏱️</text>\n            <text class=\"item-label\">从业年限</text>\n          </view>\n          <view class=\"item-right\">\n            <text class=\"item-value\">{{ doctorInfo.yearsOfPractice }}年</text>\n          </view>\n        </view>\n      </view>\n    </view>\n\n    <!-- 擅长领域 -->\n    <view class=\"info-section\">\n      <view class=\"section-title\">\n        <text class=\"title-text\">擅长领域</text>\n      </view>\n      <view class=\"specialty-container\">\n        <text class=\"specialty-text\">{{ doctorInfo.specialty }}</text>\n      </view>\n    </view>\n\n    <!-- 功能菜单 -->\n    <view class=\"menu-section\">\n      <view class=\"section-title\">\n        <text class=\"title-text\">功能设置</text>\n      </view>\n      <view class=\"menu-list\">\n        <view class=\"menu-item\" @click=\"goToScheduleManagement\">\n          <view class=\"menu-left\">\n            <text class=\"menu-icon\">📅</text>\n            <text class=\"menu-label\">我的排班</text>\n          </view>\n          <text class=\"menu-arrow\">›</text>\n        </view>\n\n        <view class=\"menu-item\" @click=\"goToStatistics\">\n          <view class=\"menu-left\">\n            <text class=\"menu-icon\">📊</text>\n            <text class=\"menu-label\">接诊统计</text>\n          </view>\n          <text class=\"menu-arrow\">›</text>\n        </view>\n\n        <view class=\"menu-item\" @click=\"goToSettings\">\n          <view class=\"menu-left\">\n            <text class=\"menu-icon\">⚙️</text>\n            <text class=\"menu-label\">系统设置</text>\n          </view>\n          <text class=\"menu-arrow\">›</text>\n        </view>\n\n        <view class=\"menu-item\" @click=\"changePassword\">\n          <view class=\"menu-left\">\n            <text class=\"menu-icon\">🔒</text>\n            <text class=\"menu-label\">修改密码</text>\n          </view>\n          <text class=\"menu-arrow\">›</text>\n        </view>\n      </view>\n    </view>\n\n    <!-- 退出登录按钮 -->\n    <view class=\"logout-section\">\n      <button class=\"logout-btn\" @click=\"logout\">退出登录</button>\n    </view>\n\n    <!-- 编辑弹窗 -->\n    <view v-if=\"editDialog.visible\" class=\"dialog-mask\" @click.self=\"closeEditDialog\">\n      <view class=\"dialog-box\">\n        <text class=\"dialog-title\">编辑{{ editDialog.label }}</text>\n        <input\n          class=\"dialog-input\"\n          v-model=\"editDialog.value\"\n          :placeholder=\"`请输入${editDialog.label}`\"\n        />\n        <view class=\"dialog-actions\">\n          <button class=\"dialog-btn cancel\" @click=\"closeEditDialog\">取消</button>\n          <button class=\"dialog-btn save\" @click=\"saveEdit\">保存</button>\n        </view>\n      </view>\n    </view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, onMounted } from 'vue'\nimport { uniNavigateTo, uniShowToast } from '@/utils/uniHelper'\nimport { useUserStore } from '../../../store/user.js'\nimport { doctorApi } from '../../../api/doctor'\n\n// 医生信息（从后端填充）\nconst doctorInfo = ref({\n  name: '',\n  title: '',\n  department: '',\n  avatar: '/static/doctor.svg',\n  phone: '',\n  email: '',\n  licenseNumber: '',\n  yearsOfPractice: 0,\n  specialty: ''\n})\n\nconst stats = ref({\n  totalPatients: 0,\n  todayPatients: 0,\n  rating: 0\n})\n\n// 加载后端医生资料（优先用当前登录用户的 userId）\nconst userStore = useUserStore()\nconst loadProfile = async () => {\n  try {\n    userStore.initFromStorage()\n    const userId = userStore.userInfo?.userId\n    let profile = null\n    if (userId) {\n      profile = await doctorApi.getProfileByUserId(userId)\n    } else {\n      profile = await doctorApi.getMyProfile()\n    }\n    if (!profile || !profile.doctorId) {\n      uniShowToast('未绑定医生资料或接口返回空数据')\n      return\n    }\n    doctorInfo.value = {\n      name: profile.doctorName || profile.realname || '',\n      title: profile.title || '',\n      department: profile.deptName || '',\n      avatar: profile.avatar || '/static/doctor.svg',\n      phone: profile.phone || '',\n      email: profile.email || '',\n      licenseNumber: profile.licenseNumber || '',\n      yearsOfPractice: profile.yearsOfPractice || 0,\n      specialty: profile.specialty || ''\n    }\n    // 可选：统计项从其它接口获取，这里占位\n    stats.value = {\n      totalPatients: 0,\n      todayPatients: 0,\n      rating: 0\n    }\n  } catch (e) {\n    uniShowToast('获取医生资料失败')\n    console.warn('loadProfile错误：', e)\n  }\n}\n\nonMounted(loadProfile)\n\n// 返回医生主界面\nfunction goBackToSchedule() {\n  const pages = getCurrentPages()\n  if (pages.length > 1) {\n    uni.navigateBack()\n  } else {\n    uniNavigateTo('/pages/doctor/schedule/main')\n  }\n}\n\n// 功能菜单\nfunction goToScheduleManagement() {\n  uniNavigateTo('/pages/doctor/schedule/main')\n}\nfunction goToStatistics() {\n  uniShowToast('接诊统计功能开发中')\n}\nfunction goToSettings() {\n  // 项目中存在 /pages/profile/profile.vue\n  uniNavigateTo('/pages/profile/profile')\n}\nfunction changePassword() {\n  uniShowToast('请前往系统设置中修改密码')\n}\n\n// 编辑弹窗\nconst editDialog = ref({\n  visible: false,\n  field: '',\n  label: '',\n  value: ''\n})\n\nfunction showEditDialog(field) {\n  const labelMap = { name: '姓名', phone: '联系电话', email: '邮箱' }\n  editDialog.value.visible = true\n  editDialog.value.field = field\n  editDialog.value.label = labelMap[field] || field\n  editDialog.value.value = doctorInfo.value[field] || ''\n}\nfunction closeEditDialog() {\n  editDialog.value.visible = false\n}\nfunction saveEdit() {\n  const { field, value } = editDialog.value\n  // 简单校验\n  if (field === 'name' && !value.trim()) {\n    uniShowToast('姓名不能为空')\n    return\n  }\n  if (field === 'phone' && !/^1[3-9]\\d{9}$/.test(value)) {\n    uniShowToast('请输入有效手机号')\n    return\n  }\n  if (field === 'email' && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value)) {\n    uniShowToast('请输入有效邮箱')\n    return\n  }\n  doctorInfo.value[field] = value\n  closeEditDialog()\n  uniShowToast('已保存')\n}\n\n// 退出登录\nfunction logout() {\n  uni.showModal({\n    title: '退出登录',\n    content: '确认退出登录？',\n    success: (res) => {\n      if (res.confirm) {\n        try {\n          uni.clearStorage()\n        } catch (e) {}\n        // 项目中登录页为 /pages/login/login.vue\n        uni.reLaunch({ url: '/subpkg/auth/login' })\n      }\n    }\n  })\n}\n</script>\n\n<style scoped>\n.profile-page {\n  min-height: 100vh;\n  padding: 24rpx;\n  box-sizing: border-box;\n  background: linear-gradient(180deg, #e9f2ff 0%, #f7f9fc 100%);\n}\n\n/* 返回按钮 */\n.back-section {\n  display: flex;\n  align-items: center;\n  color: #2a7bff;\n  font-weight: 600;\n  margin-bottom: 20rpx;\n}\n.back-icon {\n  font-size: 40rpx;\n  margin-right: 8rpx;\n}\n.back-text {\n  font-size: 28rpx;\n}\n\n/* 头部信息 */\n.profile-header {\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 8rpx 24rpx rgba(42, 123, 255, 0.08);\n  margin-bottom: 24rpx;\n}\n.avatar-section {\n  display: flex;\n  align-items: center;\n  gap: 16rpx;\n}\n.avatar {\n  width: 96rpx;\n  height: 96rpx;\n  border-radius: 999rpx;\n  background: #e9f2ff;\n}\n.doctor-basic {\n  display: flex;\n  flex-direction: column;\n}\n.doctor-name {\n  font-size: 32rpx;\n  font-weight: 700;\n  color: #1a1a1a;\n}\n.doctor-title {\n  margin-top: 4rpx;\n  font-size: 24rpx;\n  color: #7a8aa0;\n}\n.doctor-dept {\n  margin-top: 12rpx;\n}\n.dept-name {\n  display: inline-block;\n  padding: 8rpx 16rpx;\n  border-radius: 999rpx;\n  background: #e9f2ff;\n  color: #2a7bff;\n  font-size: 24rpx;\n  font-weight: 600;\n}\n\n/* 统计 */\n.stats-section {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 8rpx 24rpx rgba(42, 123, 255, 0.08);\n  margin-bottom: 24rpx;\n}\n.stat-item {\n  flex: 1;\n  text-align: center;\n}\n.stat-value {\n  font-size: 36rpx;\n  font-weight: 800;\n  color: #2f3b52;\n}\n.stat-label {\n  margin-top: 6rpx;\n  font-size: 24rpx;\n  color: #7a8aa0;\n}\n.stat-divider {\n  width: 2rpx;\n  height: 48rpx;\n  background: #f0f5ff;\n}\n\n/* 通用区块 */\n.info-section,\n.menu-section {\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 8rpx 24rpx rgba(42, 123, 255, 0.08);\n  margin-bottom: 24rpx;\n}\n.section-title {\n  margin-bottom: 12rpx;\n}\n.title-text {\n  font-size: 32rpx;\n  font-weight: 700;\n  color: #1a1a1a;\n}\n\n/* 信息列表 */\n.info-list {\n  display: flex;\n  flex-direction: column;\n  gap: 12rpx;\n}\n.info-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n}\n.item-left {\n  display: flex;\n  align-items: center;\n  gap: 12rpx;\n}\n.item-icon {\n  font-size: 28rpx;\n}\n.item-label {\n  font-size: 26rpx;\n  color: #7a8aa0;\n}\n.item-right {\n  display: flex;\n  align-items: center;\n  gap: 8rpx;\n}\n.item-value {\n  font-size: 28rpx;\n  color: #2f3b52;\n  font-weight: 600;\n}\n.item-arrow {\n  font-size: 40rpx;\n  color: #a0b7e0;\n}\n\n/* 擅长领域 */\n.specialty-container {\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n}\n.specialty-text {\n  font-size: 26rpx;\n  color: #2f3b52;\n}\n\n/* 菜单 */\n.menu-list {\n  display: flex;\n  flex-direction: column;\n  gap: 12rpx;\n}\n.menu-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n}\n.menu-left {\n  display: flex;\n  align-items: center;\n  gap: 12rpx;\n}\n.menu-icon {\n  font-size: 28rpx;\n}\n.menu-label {\n  font-size: 26rpx;\n  color: #2f3b52;\n}\n.menu-arrow {\n  font-size: 40rpx;\n  color: #a0b7e0;\n}\n\n/* 退出登录 */\n.logout-section {\n  margin-top: 12rpx;\n}\n.logout-btn {\n  width: 100%;\n  border: none;\n  border-radius: 12rpx;\n  padding: 24rpx 0;\n  color: #fff;\n  font-size: 28rpx;\n  font-weight: 700;\n  background: linear-gradient(90deg, #ff3b30, #ff6b6b);\n  box-shadow: 0 12rpx 20rpx rgba(255, 59, 48, 0.24);\n}\n\n/* 编辑弹窗 */\n.dialog-mask {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.35);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 999;\n}\n.dialog-box {\n  width: 80%;\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 12rpx 20rpx rgba(42, 123, 255, 0.16);\n}\n.dialog-title {\n  font-size: 30rpx;\n  font-weight: 700;\n  color: #1a1a1a;\n}\n.dialog-input {\n  margin-top: 16rpx;\n  width: 100%;\n  height: 72rpx;\n  border-radius: 12rpx;\n  background: #f8fafc;\n  padding: 0 16rpx;\n  box-sizing: border-box;\n  font-size: 26rpx;\n  color: #2f3b52;\n}\n.dialog-actions {\n  margin-top: 16rpx;\n  display: flex;\n  justify-content: flex-end;\n  gap: 12rpx;\n}\n.dialog-btn {\n  border: none;\n  border-radius: 12rpx;\n  padding: 16rpx 24rpx;\n  font-size: 26rpx;\n  font-weight: 700;\n}\n.dialog-btn.cancel {\n  background: #e9f2ff;\n  color: #2a7bff;\n}\n.dialog-btn.save {\n  background: linear-gradient(90deg, #2a7bff, #6aa9ff);\n  color: #fff;\n}\n</style>","import MiniProgramPage from 'D:/HuaweiMoveData/Users/zheng/Documents/GitHub/lh7772/校医院挂号系统/pages/doctor/profile/index.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","useUserStore","doctorApi","uniShowToast","uni","onMounted","uniNavigateTo"],"mappings":";;;;;;;;AAiNA,UAAM,aAAaA,cAAAA,IAAI;AAAA,MACrB,MAAM;AAAA,MACN,OAAO;AAAA,MACP,YAAY;AAAA,MACZ,QAAQ;AAAA,MACR,OAAO;AAAA,MACP,OAAO;AAAA,MACP,eAAe;AAAA,MACf,iBAAiB;AAAA,MACjB,WAAW;AAAA,IACb,CAAC;AAED,UAAM,QAAQA,cAAAA,IAAI;AAAA,MAChB,eAAe;AAAA,MACf,eAAe;AAAA,MACf,QAAQ;AAAA,IACV,CAAC;AAGD,UAAM,YAAYC,WAAAA,aAAc;AAChC,UAAM,cAAc,YAAY;;AAC9B,UAAI;AACF,kBAAU,gBAAiB;AAC3B,cAAM,UAAS,eA